            {"question":"The social worker and nurse may work together to:","options":["Prepare couples for marriage and parenthood","Perform neonatal resuscitation","Perform obstetric surgery","Calculate Apgar scores only"],"answer":"Prepare couples for marriage and parenthood"},
            {"question":"MCH health education covers:","options":["Antenatal period only","Natal period only","Postnatal period only","Antenatal, natal, and postnatal periods"],"answer":"Antenatal, natal, and postnatal periods"},
