            {"question":"Which investigation is associated with screening suspected TB cases during premarital assessment?","options":["X-ray","Urine albumin","Blood pressure measurement","Breast examination"],"answer":"X-ray"},
            {"question":"Which pair is identified through blood investigation during premarital assessment?","options":["Syphilis and Rh factor","TB and renal disease","Edema and varicose veins","Diabetes and hypertension only"],"answer":"Syphilis and Rh factor"},
            {"question":"Urine investigation for albuminuria is particularly useful for investigating:","options":["TB","Kidney disease, especially hypertension","Rh incompatibility","Breast disease"],"answer":"Kidney disease, especially hypertension"},
