            {"question":"Gerontology is the study of:","options":["Diseases of older adults only","Physical, psychological, social, and spiritual aspects of old age","Nursing procedures for elderly patients only","Medical treatment of chronic diseases"],"answer":"Physical, psychological, social, and spiritual aspects of old age"},
            {"question":"Geriatrics is:","options":["The study of social aspects of aging","A branch of general medicine concerned with diseases and illness of older adults","A branch of nursing concerned with elderly care","The study of retirement and social security"],"answer":"A branch of general medicine concerned with diseases and illness of older adults"},
            {"question":"Gerontological nursing is primarily concerned with:","options":["Diagnosing diseases only","Assessment, planning, implementation, and evaluation of care for older adults","Providing social services only","Treating psychiatric disorders only"],"answer":"Assessment, planning, implementation, and evaluation of care for older adults"},
            {"question":"According to the lecture, an elderly person is someone who is:","options":["55 years or older","60 years or older","65 years or older","70 years or older"],"answer":"60 years or older"},
            {"question":"Life expectancy refers to:","options":["The maximum possible age of a person","The average number of years a person can be expected to live","The number of healthy years after retirement","The age at which chronic disease begins"],"answer":"The average number of years a person can be expected to live"},
            {"question":"The social position of older people is determined mainly by:","options":["Age alone","Culture","Income only","Physical health only"],"answer":"Culture"},
            {"question":"Ageism refers to:","options":["Positive attitudes toward older adults","An unfavorable and prejudiced attitude toward older adults simply because they are old","Fear of retirement","Social isolation caused by disease"],"answer":"An unfavorable and prejudiced attitude toward older adults simply because they are old"},
            {"question":"Stereotypes are best described as:","options":["Accurate beliefs based on individual assessment","Simplified and often untrue beliefs that reinforce negative images of older people","Medical diagnoses of elderly patients","Social roles assigned by healthcare workers"],"answer":"Simplified and often untrue beliefs that reinforce negative images of older people"},
            {"question":"A person aged 68 years is classified as:","options":["Old-old","Very old","Young old","Centenarian"],"answer":"Young old"},
            {"question":"An elderly person aged 80 years belongs to which category?","options":["Young old","Old-old","Very old","Centenarian"],"answer":"Old-old"},
            {"question":"A person aged 90 years is classified as:","options":["Young old","Old-old","Very old","Centenarian"],"answer":"Very old"},
            {"question":"A person aged 100 years or older is called a:","options":["Very old","Old-old","Centenarian","Super elderly"],"answer":"Centenarian"},
            {"question":"According to the lecture, the majority of centenarians will be:","options":["Men","Women","Equally divided between men and women","Children of elderly parents"],"answer":"Women"},
            {"question":"Which statement about normal age-related physical changes is MOST correct?","options":["They occur suddenly and are identical in all people.","They are gradual and vary in rate and degree among individuals.","They occur only when disease is present.","They are completely preventable through medication."],"answer":"They are gradual and vary in rate and degree among individuals."},
            {"question":"Which factor may increase the speed and degree of age-related physical changes?","options":["Disease","Age classification only","Education","Occupation only"],"answer":"Disease"},
            {"question":"Which combination can influence the rate and degree of age-related changes?","options":["Lifestyle, nutrition, economic status, and social environment","Blood group, height, and eye color","Occupation only","Education and marital status only"],"answer":"Lifestyle, nutrition, economic status, and social environment"},
            {"question":"Recognizing normal age-related changes can help an older adult:","options":["Stop the aging process","Adapt and cope with the changes","Avoid all medical care","Prevent all physical changes"],"answer":"Adapt and cope with the changes"},
            {"question":"Which integumentary change is expected with aging?","options":["Increased skin elasticity","Dry, fragile, less elastic skin","Increased production of skin cells","Increased activity of sweat glands"],"answer":"Dry, fragile, less elastic skin"},
            {"question":"Which change contributes to dry skin in older adults?","options":["Increased activity of oil and sweat glands","Decreased activity of oil and sweat glands","Increased circulation","Increased production of new skin cells"],"answer":"Decreased activity of oil and sweat glands"},
            {"question":"Which skin finding is specifically mentioned as a normal age-related change?","options":["Bright red skin lesions","Dark yellow or brown colored spots","Increased pigmentation only on the palms","Complete loss of skin color"],"answer":"Dark yellow or brown colored spots"},
            {"question":"Old age develops through a long process rather than occurring suddenly.","options":["True","False"],"answer":"True"},
            {"question":"Healthy lifestyles established early in life can help delay aging and maintain quality of life.","options":["True","False"],"answer":"True"},
            {"question":"Gerontology focuses only on diseases affecting older adults.","options":["True","False"],"answer":"False"},
            {"question":"Geriatrics is a branch of general medicine concerned with diseases and illness of older adults.","options":["True","False"],"answer":"True"},
            {"question":"Gerontological nursing includes assessment, planning, implementation, and evaluation of care.","options":["True","False"],"answer":"True"},
            {"question":"According to the lecture, an elderly person is 60 years or more.","options":["True","False"],"answer":"True"},
            {"question":"Ageism refers to favorable attitudes toward older adults.","options":["True","False"],"answer":"False"},
            {"question":"Stereotypes are always accurate beliefs about older adults.","options":["True","False"],"answer":"False"},
            {"question":"People aged 75–84 years are classified as old-old.","options":["True","False"],"answer":"True"},
            {"question":"People aged 100 years and older are classified as centenarians.","options":["True","False"],"answer":"True"},
            {"question":"Which age-related change occurs to hair?","options":["Hair becomes thicker and darker","Hair loses color and becomes gray","Hair growth increases","Hair becomes more elastic"],"answer":"Hair loses color and becomes gray"},
            {"question":"Which nail change is expected with aging?","options":["Nails become soft and flexible","Nails become thin and smooth","Nails become thick and brittle","Nails become more elastic"],"answer":"Nails become thick and brittle"},
            {"question":"An older adult complains of increased sensitivity to temperature. This finding is:","options":["An expected age-related integumentary change","A sign of increased sweat gland activity","A sign of increased skin elasticity","An indication of improved circulation"],"answer":"An expected age-related integumentary change"},
            {"question":"Which intervention is MOST appropriate for routine skin care in an older adult?","options":["Use strong soap frequently","Use mild soap","Avoid moisturizing products","Bathe several times every day"],"answer":"Use mild soap"},
            {"question":"According to the lecture, oils or lanolin lotion are recommended to:","options":["Improve hearing","Provide skin care","Increase circulation","Prevent cataracts"],"answer":"Provide skin care"},
            {"question":"How often does the lecture recommend bathing or showering for an older adult?","options":["Several times daily","Once or twice a week","Once every two weeks","Only when sweating occurs"],"answer":"Once or twice a week"},
            {"question":"Which intervention is recommended to alleviate an older person's feeling of coldness?","options":["Avoid layers of clothing","Use socks, sweaters, and layers of clothing","Use cold-water baths","Reduce clothing during winter"],"answer":"Use socks, sweaters, and layers of clothing"},
            {"question":"Which statement about the cardiovascular system with aging is CORRECT?","options":["Heart size increases significantly","Cardiac output increases","Heart size does not change with age","Heart muscle becomes more elastic"],"answer":"Heart size does not change with age"},
            {"question":"Which cardiovascular change occurs with aging?","options":["Increased cardiac output","Increased elasticity of arteries","Decreased cardiac output","Increased heart rate"],"answer":"Decreased cardiac output"},
