            {"question":"A decreased cough reflex in an older adult may lead to:","options":["Increased removal of mucus","Decreased removal of mucus","Increased gas exchange","Increased respiratory muscle strength"],"answer":"Decreased removal of mucus"},
            {"question":"The decreased efficiency of the respiratory system in older adults may increase susceptibility to:","options":["Cold and pneumonia","Cataracts and glaucoma","Constipation and dysphagia","Arthritis and kyphosis"],"answer":"Cold and pneumonia"},
            {"question":"Which positioning is recommended to improve respiratory care during sleep?","options":["Prone position","Trendelenburg position","Semi-Fowler's position with 2 or 3 pillows","Flat supine position without pillows"],"answer":"Semi-Fowler's position with 2 or 3 pillows"},
