            {"question":"Hair commonly loses its color and becomes gray with aging.","options":["True","False"],"answer":"True"},
            {"question":"Nails usually become thin and flexible with aging.","options":["True","False"],"answer":"False"},
            {"question":"Mild soap is recommended for skin care in older adults.","options":["True","False"],"answer":"True"},
