            {"question":"Which combination contains only psychosocial needs identified in the lecture?","options":["Independence, social interaction, purpose in life","Nutrition, exercise, sleep","Financial security, medication, screening","Accident prevention, exercise, immunization"],"answer":"Independence, social interaction, purpose in life"},
            {"question":"Which of the following is included in the elderly person's need for safety, love, and belonging?","options":["Feeling socially connected and secure","Increasing financial burden","Avoiding all relationships","Increasing dependency"],"answer":"Feeling socially connected and secure"},
