            {"question":"The lecture recommends exercising in areas with other exercisers because this can help maintain motivation.","options":["True","False"],"answer":"True"},
            {"question":"A nurse is conducting a home safety assessment for an elderly client. Which approach is MOST comprehensive according to the lecture?","options":["Assess only the bedroom and bathroom","Assess only outdoor areas","Assess both indoor and outdoor areas of the home","Assess only areas where the client reports previous accidents"],"answer":"Assess both indoor and outdoor areas of the home"},
            {"question":"Which of the following is an indoor area that should be included when assessing an elderly person's home?","options":["Balcony","Garage door","Stairway","Kitchen"],"answer":"Kitchen"},
