            {"question":"Budgeting helps allocate personnel and supplies.","options":["True","False"],"answer":"True"},
            {"question":"Facilities and support services may be included in budget allocation.","options":["True","False"],"answer":"True"},
            {"question":"Planning is a function of budgets.","options":["True","False"],"answer":"True"},
            {"question":"Coordination is a function of budgets.","options":["True","False"],"answer":"True"},
            {"question":"Motivation is listed as a budget function.","options":["True","False"],"answer":"True"},
            {"question":"Control is unrelated to budgets.","options":["True","False"],"answer":"False"},
            {"question":"Communication is one of the functions of budgets.","options":["True","False"],"answer":"True"},
            {"question":"Failure to budget may result in not having an emergency fund.","options":["True","False"],"answer":"True"},
            {"question":"Not budgeting guarantees the ability to expand into new markets.","options":["True","False"],"answer":"False"},
            {"question":"Failure to budget may make it difficult to secure investment dollars.","options":["True","False"],"answer":"True"},
            {"question":"Failure to budget may potentially lead to shutting down because of debt.","options":["True","False"],"answer":"True"},
            {"question":"Failure to budget can strain business relationships.","options":["True","False"],"answer":"True"},
            {"question":"Failure to budget makes securing loans easier.","options":["True","False"],"answer":"False"},
            {"question":"The first budgetary step is to assess what needs to be covered.","options":["True","False"],"answer":"True"},
            {"question":"Developing a plan comes before assessing what needs to be covered.","options":["True","False"],"answer":"False"},
            {"question":"Implementation follows development of the budget plan.","options":["True","False"],"answer":"True"},
            {"question":"Evaluation is the final step shown in the budgetary process.","options":["True","False"],"answer":"True"},
            {"question":"An effective budget should be based on organizational objectives and standards.","options":["True","False"],"answer":"True"},
            {"question":"An effective budget should be complex and rigid.","options":["True","False"],"answer":"False"},
            {"question":"An effective budget should be simple and flexible.","options":["True","False"],"answer":"True"},
            {"question":"An effective budget should be balanced and economic.","options":["True","False"],"answer":"True"},
            {"question":"An effective budget should be fair and objective.","options":["True","False"],"answer":"True"},
            {"question":"An effective budget should be based primarily on uncontrollable factors.","options":["True","False"],"answer":"False"},
            {"question":"An effective budget should be outcome oriented.","options":["True","False"],"answer":"True"},
            {"question":"Personnel, operating, capital, and cash are the four types of budgets shown in the lecture.","options":["True","False"],"answer":"True"},
            {"question":"The personnel budget is the largest budget in healthcare.","options":["True","False"],"answer":"True"},
            {"question":"Healthcare is described as labor-intensive.","options":["True","False"],"answer":"True"},
            {"question":"Personnel budget includes only productive time.","options":["True","False"],"answer":"False"},
            {"question":"Actual working hours represent productive time.","options":["True","False"],"answer":"True"},
            {"question":"Breaks, benefits, and leave are examples of non-productive paid time.","options":["True","False"],"answer":"True"},
            {"question":"Monitoring personnel time can help avoid under- or over-staffing.","options":["True","False"],"answer":"True"},
            {"question":"The operating budget reflects expenses that change in response to service volume.","options":["True","False"],"answer":"True"},
            {"question":"Electricity is included in the operating budget.","options":["True","False"],"answer":"True"},
            {"question":"Repair and maintenance are included in the operating budget.","options":["True","False"],"answer":"True"},
            {"question":"The capital budget is mainly for daily supplies.","options":["True","False"],"answer":"False"},
            {"question":"Capital budgets plan for buildings or major equipment.","options":["True","False"],"answer":"True"},
            {"question":"Capital equipment usually has a life greater than five to seven years.","options":["True","False"],"answer":"True"},
            {"question":"The cash budget is described as the lifeblood of an organization.","options":["True","False"],"answer":"True"},
            {"question":"The cash budget is an operating plan for monthly cash receipts and disbursements.","options":["True","False"],"answer":"True"},
            {"question":"Organizational survival is unrelated to paying bills on time.","options":["True","False"],"answer":"False"},
            {"question":"A major piece of equipment expected to last eight years would fit the capital budget.","options":["True","False"],"answer":"True"},
            {"question":"A budget for electricity and routine maintenance would be classified as a capital budget.","options":["True","False"],"answer":"False"},
            {"question":"A monthly plan for cash receipts and disbursements is a cash budget.","options":["True","False"],"answer":"True"},
            {"question":"The four budget types shown in the lecture are personnel, operating, capital, and cash.","options":["True","False"],"answer":"True"},
